import SwiftUI
import AppKit

// MARK: - Configuration

/// Everything that defines how a bot's Orb looks. Option ids match `Resources/Orbs/options.json`,
/// which is generated by `art/orbs.py manifest` from the same catalog that renders the layers.
struct OrbConfig: Hashable, Codable, Sendable {
    var color = "indigo"
    var eyes = "pilulas"
    var mouth = "nenhuma"
    var brows = "nenhuma"
    var cheeks = "nenhuma"
    var mustache = "nenhum"
    var hair = "nenhum"
    var accessories: [String] = []
    /// Optional tints (sRGB hex). nil = automatic default.
    var hairColor: UInt32?
    var mustacheColor: UInt32?
    var accentColor: UInt32?

    static func random() -> OrbConfig {
        let catalog = OrbCatalog.shared
        func pick(_ category: OrbCategory, emptyWeight: Double = 0) -> String {
            let options = catalog.options(category)
            if let first = options.first, Double.random(in: 0..<1) < emptyWeight { return first.id }
            return options.randomElement()?.id ?? ""
        }
        var config = OrbConfig()
        config.color = catalog.palettes.randomElement()?.id ?? "indigo"
        config.eyes = pick(.eyes)
        config.mouth = pick(.mouth, emptyWeight: 0.3)
        config.brows = pick(.brows, emptyWeight: 0.6)
        config.cheeks = pick(.cheeks, emptyWeight: 0.5)
        config.mustache = pick(.mustache, emptyWeight: 0.7)
        config.hair = pick(.hair, emptyWeight: 0.5)
        if Bool.random(), let accessory = catalog.options(.accessories).randomElement() {
            config.accessories = [accessory.id]
        }
        return config
    }

    func value(for category: OrbCategory) -> String {
        switch category {
        case .color: color
        case .eyes: eyes
        case .mouth: mouth
        case .brows: brows
        case .cheeks: cheeks
        case .mustache: mustache
        case .hair: hair
        case .accessories: accessories.first ?? ""
        }
    }

    mutating func set(_ category: OrbCategory, _ id: String) {
        switch category {
        case .color: color = id
        case .eyes: eyes = id
        case .mouth: mouth = id
        case .brows: brows = id
        case .cheeks: cheeks = id
        case .mustache: mustache = id
        case .hair: hair = id
        case .accessories:
            if let index = accessories.firstIndex(of: id) { accessories.remove(at: index) } else { accessories.append(id) }
        }
    }
}

enum OrbCategory: String, CaseIterable, Identifiable, Sendable {
    case color, eyes, mouth, brows, cheeks, mustache, hair, accessories

    var id: String { rawValue }

    var label: String {
        switch self {
        case .color: "Cor"
        case .eyes: "Olhos"
        case .mouth: "Boca"
        case .brows: "Sobrancelhas"
        case .cheeks: "Bochechas"
        case .mustache: "Bigode"
        case .hair: "Cabelo"
        case .accessories: "Acessórios"
        }
    }

    var symbol: String {
        switch self {
        case .color: "paintpalette"
        case .eyes: "eye"
        case .mouth: "mouth"
        case .brows: "eyebrow"
        case .cheeks: "face.smiling"
        case .mustache: "mustache"
        case .hair: "comb"
        case .accessories: "eyeglasses"
        }
    }
}

// MARK: - Catalog (options.json)

struct OrbOption: Identifiable, Hashable, Sendable {
    let id: String
    let label: String
}

struct OrbPalette: Identifiable, Hashable, Sendable {
    let id: String
    let label: String
    /// rim, core, deep, glow
    let hexes: [UInt32]

    var core: Color { Color(hex: hexes[1]) }
    var glow: Color { Color(hex: hexes[3]) }
    var deep: UInt32 { hexes[2] }
    var isLight: Bool { OrbCatalog.lightPalettes.contains(id) }
}

final class OrbCatalog: Sendable {
    static let shared = OrbCatalog()
    static let lightPalettes: Set<String> = ["perola", "algodao"]

    let palettes: [OrbPalette]
    private let categories: [OrbCategory: [OrbOption]]
    let tintedAccessories: Set<String>
    let root: URL?

    private init() {
        let candidates: [URL?] = [
            Bundle.main.resourceURL?.appendingPathComponent("Orbs"),
            URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
                .appendingPathComponent("Resources/Orbs")
        ]
        root = candidates.compactMap { $0 }.first {
            FileManager.default.fileExists(atPath: $0.appendingPathComponent("options.json").path)
        }

        var palettes: [OrbPalette] = []
        var categories: [OrbCategory: [OrbOption]] = [:]
        var tinted: Set<String> = []
        if let root, let data = try? Data(contentsOf: root.appendingPathComponent("options.json")),
           let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {
            for entry in json["color"] as? [[String: Any]] ?? [] {
                let hexes = (entry["hex"] as? [String] ?? []).compactMap { UInt32($0.dropFirst(), radix: 16) }
                if let id = entry["id"] as? String, let label = entry["label"] as? String, hexes.count == 4 {
                    palettes.append(OrbPalette(id: id, label: label, hexes: hexes))
                }
            }
            for category in OrbCategory.allCases where category != .color {
                categories[category] = (json[category.rawValue] as? [[String: Any]] ?? []).compactMap { entry in
                    guard let id = entry["id"] as? String, let label = entry["label"] as? String else { return nil }
                    return OrbOption(id: id, label: label)
                }
            }
            tinted = Set(json["tintedAccessories"] as? [String] ?? [])
        }
        self.palettes = palettes
        self.categories = categories
        self.tintedAccessories = tinted
    }

    func options(_ category: OrbCategory) -> [OrbOption] {
        category == .color ? palettes.map { OrbOption(id: $0.id, label: $0.label) } : categories[category] ?? []
    }

    func palette(_ id: String) -> OrbPalette {
        palettes.first { $0.id == id } ?? palettes.first ?? OrbPalette(id: "indigo", label: "Índigo",
                                                                        hexes: [0xE4DEFF, 0x4A34F2, 0x3D2BE4, 0x86DFFF])
    }

    func label(_ category: OrbCategory, _ id: String) -> String {
        options(category).first { $0.id == id }?.label ?? id
    }
}

// MARK: - Layer images

@MainActor
enum OrbImages {
    private static var cache: [String: NSImage] = [:]

    /// Layer image downsampled to the nearest size bucket for `pixels` (keeps per-frame compositing cheap).
    static func image(_ relativePath: String, pixels: CGFloat) -> NSImage? {
        let bucket = [96, 160, 256, 384, 640].first { CGFloat($0) >= pixels } ?? 640
        let key = "\(relativePath)@\(bucket)"
        if let cached = cache[key] { return cached }
        guard let original = original(relativePath) else { return nil }
        let image = bucket >= 640 ? original : resized(original, to: bucket)
        cache[key] = image
        return image
    }

    private static var cgCache: [String: CGImage] = [:]

    /// Bitmap for Core Animation layers, with the multiply tint baked in (layers can't multiply cheaply).
    static func cgImage(_ relativePath: String, pixels: CGFloat, tint: UInt32?) -> CGImage? {
        let bucket = [96, 160, 256, 384, 640].first { CGFloat($0) >= pixels } ?? 640
        let key = "\(relativePath)@\(bucket)#\(tint.map { String($0, radix: 16) } ?? "-")"
        if let cached = cgCache[key] { return cached }
        guard let source = original(relativePath)?.cgImage(forProposedRect: nil, context: nil, hints: nil),
              let context = CGContext(data: nil, width: bucket, height: bucket, bitsPerComponent: 8, bytesPerRow: 0,
                                      space: CGColorSpace(name: CGColorSpace.sRGB)!,
                                      bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
        let rect = CGRect(x: 0, y: 0, width: bucket, height: bucket)
        context.interpolationQuality = .high
        context.draw(source, in: rect)
        if let tint {
            context.setBlendMode(.multiply)
            context.setFillColor(NSColor(hex: tint).cgColor)
            context.fill(rect)
            context.setBlendMode(.destinationIn)
            context.draw(source, in: rect)
        }
        let image = context.makeImage()
        cgCache[key] = image
        return image
    }

    private static func original(_ relativePath: String) -> NSImage? {
        let key = relativePath + "@full"
        if let cached = cache[key] { return cached }
        guard let root = OrbCatalog.shared.root,
              let image = NSImage(contentsOf: root.appendingPathComponent(relativePath + ".png")) else { return nil }
        cache[key] = image
        return image
    }

    private static func resized(_ image: NSImage, to side: Int) -> NSImage {
        guard let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: side, pixelsHigh: side, bitsPerSample: 8,
                                         samplesPerPixel: 4, hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB,
                                         bytesPerRow: 0, bitsPerPixel: 0) else { return image }
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
        NSGraphicsContext.current?.imageInterpolation = .high
        image.draw(in: NSRect(x: 0, y: 0, width: side, height: side))
        NSGraphicsContext.restoreGraphicsState()
        let result = NSImage(size: NSSize(width: side, height: side))
        result.addRepresentation(rep)
        return result
    }
}

/// One composited layer: an image path plus an optional multiply tint.
struct OrbLayer: Identifiable, Hashable {
    enum Kind { case body, cheeks, mouth, mustache, brows, eyes, hair, accessory }
    let kind: Kind
    let path: String
    let tint: UInt32?
    var id: String { path }
}

extension OrbConfig {
    /// Layers back-to-front, with activity overrides for eyes/mouth/brows applied.
    func layers(eyes eyesOverride: String? = nil, mouth mouthOverride: String? = nil,
                brows browsOverride: String? = nil) -> [OrbLayer] {
        let palette = OrbCatalog.shared.palette(color)
        let variant = palette.isLight ? "-dark" : ""
        var layers = [OrbLayer(kind: .body, path: "body/\(color)", tint: nil)]
        if cheeks != "nenhuma" { layers.append(OrbLayer(kind: .cheeks, path: "cheeks/\(cheeks)", tint: nil)) }
        let mouthID = mouthOverride ?? mouth
        if mouthID != "nenhuma" { layers.append(OrbLayer(kind: .mouth, path: "mouth/\(mouthID)\(variant)", tint: nil)) }
        if mustache != "nenhum" {
            layers.append(OrbLayer(kind: .mustache, path: "mustache/\(mustache)", tint: mustacheColor ?? 0xF4F2FF))
        }
        let browsID = browsOverride ?? brows
        if browsID != "nenhuma" { layers.append(OrbLayer(kind: .brows, path: "brows/\(browsID)\(variant)", tint: nil)) }
        layers.append(OrbLayer(kind: .eyes, path: "eyes/\(eyesOverride ?? eyes)\(variant)", tint: nil))
        if hair != "nenhum" {
            layers.append(OrbLayer(kind: .hair, path: "hair/\(hair)", tint: hairColor ?? Self.darkened(palette.deep, 0.55)))
        }
        for accessory in accessories {
            let tint = OrbCatalog.shared.tintedAccessories.contains(accessory)
                ? (accentColor ?? Self.defaultAccent(accessory, palette: palette)) : nil
            layers.append(OrbLayer(kind: .accessory, path: "accessories/\(accessory)", tint: tint))
        }
        return layers
    }

    static func defaultAccent(_ accessory: String, palette: OrbPalette) -> UInt32 {
        switch accessory {
        case "bone": 0xFF5A3D
        case "gorro": 0xFF6B4A
        case "laco": 0xFF4F8B
        case "fones": 0x2B2B36
        case "chifres": 0xE0303F
        case "flor": 0xFFFFFF
        case "orelhas-gato": palette.deep
        default: 0xFFFFFF
        }
    }

    static func darkened(_ hex: UInt32, _ factor: Double) -> UInt32 {
        [16, 8, 0].reduce(UInt32(0)) { result, shift in
            result | (UInt32(Double((hex >> UInt32(shift)) & 0xFF) * factor) << UInt32(shift))
        }
    }
}
